INSERT INTO "evaluaciones" ("id_evaluacion", "id_empleado", "fecha", "puntuacion", "observaciones") VALUES
(1, 140, '2026-01-11', 75.63, 'Omnis dens commemoro eveniet consuasor abduco vilicus.'),
(2, 1, '2024-12-28', 64.96, 'Umquam dolorum cohibeo conqueror officiis tenuis atque defero aedificium.'),
(3, 49, '2023-08-12', 15.37, 'Statua currus aegrus iusto repudiandae charisma abeo tenax bis.'),
(4, 150, '2025-12-24', 77.2, 'Subseco defaeco cohibeo armarium umerus.'),
(5, 99, '2026-04-16', 92.33, 'Avaritia tamquam viriliter umquam teneo aggero cernuus curso cui corrumpo.'),
