(16, 17, '2025-01-12', 54.74, 'Ultio creta suasoria.'),
(17, 112, '2026-01-05', 26.79, 'Curriculum victus teres.'),
(18, 135, '2025-07-21', 33.84, 'Enim antea debitis.'),
(19, 131, '2025-07-16', 38.89, 'Suppono demoror abscido avarus abscido sint.'),
(20, 47, '2026-03-08', 30.76, 'Vox vorago speculum vulgus tantum ab super quasi solum sumptus.'),
(21, 41, '2025-12-06', 66.04, 'Subiungo adfero adeo turpis veritatis eos utpote circumvenio tenax ater.'),
(22, 33, '2025-10-04', 88.92, 'Contra dedecor clarus tergo nesciunt virtus tamquam depereo conqueror certe.'),
